(async function(){
  const response=await fetch('../../openspec/changes/expand-feature-research/evidence/campaign.json.gz'),c=JSON.parse(await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).text()),F=window.SpaceFoxF,R=window.SpaceFoxFR,all=c.generations.flatMap(g=>g.candidates),permutation=[9,0,5,10,2,8,7,11,1,6,3,4];
  for(const a of F.axes){const o=document.createElement('option');o.value=a.id;o.textContent=a.id;document.querySelector('#axis').append(o);}
  function paint(){const axis=document.querySelector('#axis').value,s=c.training[Number(document.querySelector('#scene').value)],items=all.filter(x=>x.axis===axis),grid=document.querySelector('#grid');grid.replaceChildren();permutation.forEach((n,i)=>{const item=items[n];if(!item)return;const card=document.createElement('article');card.className='sheet-card';const title=document.createElement('h2');title.textContent=String.fromCharCode(65+i);const p=document.createElement('div');p.className='sheet-preview';p.append(R.render(item,s));card.append(title,p);grid.append(card);});document.querySelector('#status').textContent=`${axis} · 12 уровней/потомков · ${s.clock} · ${s.fixture.rocket.displayLabel}`;}
  document.querySelector('#axis').onchange=paint;document.querySelector('#scene').onchange=paint;await Promise.all([...new Set(Object.values(F.fonts))].map(f=>document.fonts.load(`600 80px '${f}'`)));await document.fonts.load("500 21px 'Noto Sans'",'Россия USA');await document.fonts.ready;paint();
})();
